def is_additive_number(num):
    n = len(num)

    def valid_piece(piece):
        return piece == "0" or piece[0] != "0"

    def add_strings(a, b):
        return str(int(a) + int(b))

    for i in range(1, n):
        first = num[:i]
        if not valid_piece(first):
            break
        for j in range(i + 1, n):
            second = num[i:j]
            if not valid_piece(second):
                break
            a, b = first, second
            pos = j
            while pos < n:
                expected = add_strings(a, b)
                if num[pos:pos + len(expected)] != expected:
                    break
                pos += len(expected)
                a, b = b, expected
            if pos == n:
                return True
    return False

